class Solution {
public:
    string stoneGameIII(vector<int>& stoneValue) {
        int n = stoneValue.size();
        long long a = 0, b = 0, c = 0;

        for (int i = n - 1; i >= 0; i--) {
            long long best = stoneValue[i] - a;
            if (i + 1 < n) {
                long long sum2 = (long long)stoneValue[i] + stoneValue[i + 1];
                best = max(best, sum2 - b);
            }
            if (i + 2 < n) {
                long long sum3 = (long long)stoneValue[i] + stoneValue[i + 1] + stoneValue[i + 2];
                best = max(best, sum3 - c);
            }
            c = b;
            b = a;
            a = best;
        }

        if (a > 0) return "Alice";
        if (a < 0) return "Bob";
        return "Tie";
    }
};
